using Notifications.Legacy;

namespace Notifications;

/// <summary>Sends push notifications.</summary>
public sealed class PushClient
{
    private readonly IPushProvider _pushProvider;

    public PushClient()
        : this(new DefaultPushProvider())
    {
    }

    public PushClient(IPushProvider pushProvider)
    {
        _pushProvider = pushProvider ?? throw new System.ArgumentNullException(nameof(pushProvider));
    }

    public bool SendPush(Message message)
    {
        return _pushProvider.Deliver(
            message.Recipient.Name,
            message.Subject,
            message.Body);
    }
}
